import React, { useEffect, useState } from 'react';
import api from '../../services/api';

const imgUrl = (fn) => fn ? `https://localhost:7113/api/${fn}` : null;

const InfoRow = ({ label, value }) => (
  <div className="col-md-6 mb-2">
    <small className="text-muted d-block" style={{ fontSize: '0.72rem', letterSpacing: '0.04em', textTransform: 'uppercase' }}>{label}</small>
    <div className="fw-semibold text-dark" style={{ fontSize: '0.92rem' }}>{value || '—'}</div>
  </div>
);

const OrderViewModal = ({ orderId, onClose }) => {
  const [order, setOrder] = useState(null);
  const [loading, setLoading] = useState(true);
  const [imgViewer, setImgViewer] = useState(null);

  useEffect(() => {
    if (!orderId) return;
    setLoading(true);
    api.get(`https://localhost:7113/api/order/GetOrderView?orderID=${orderId}`)
      .then(r => setOrder(r.data))
      .catch(() => {})
      .finally(() => setLoading(false));
  }, [orderId]);

  // Close on Escape key
  useEffect(() => {
    const handler = (e) => { if (e.key === 'Escape') onClose(); };
    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, [onClose]);

  if (!orderId) return null;

  return (
    <>
      {/* Backdrop */}
      <div
        onClick={onClose}
        style={{
          position: 'fixed', inset: 0,
          background: 'rgba(15, 23, 42, 0.55)',
          backdropFilter: 'blur(3px)',
          zIndex: 1050,
        }}
      />

      {/* Modal Panel */}
      <div
        style={{
          position: 'fixed',
          top: '50%', left: '50%',
          transform: 'translate(-50%, -50%)',
          width: 'min(780px, 96vw)',
          maxHeight: '90vh',
          background: '#fff',
          borderRadius: 16,
          boxShadow: '0 24px 64px rgba(0,0,0,0.22)',
          zIndex: 1051,
          display: 'flex',
          flexDirection: 'column',
          overflow: 'hidden',
        }}
      >
        {/* Header */}
        <div style={{
          padding: '18px 24px',
          borderBottom: '1px solid #e9ecef',
          display: 'flex', alignItems: 'center', justifyContent: 'space-between',
          background: '#f8f9fb',
        }}>
          <div>
            <span style={{ fontSize: '0.72rem', textTransform: 'uppercase', letterSpacing: '0.08em', color: '#6c757d' }}>Order Details</span>
            <h6 className="mb-0 fw-bold mt-1" style={{ fontSize: '1rem' }}>
              {order ? `#${order.orderNumber || order.order__Number || orderId}` : '—'}
            </h6>
          </div>
          <div className="d-flex align-items-center gap-3">
            {order?.status && (
              <span className={`badge rounded-pill px-3 py-2 ${
                order.status === 'completed' ? 'bg-success' :
                order.status === 'cancelled' ? 'bg-danger' :
                order.status === 'pending' ? 'bg-warning text-dark' :
                'bg-primary'
              }`} style={{ fontSize: '0.75rem' }}>
                {order.status.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase())}
              </span>
            )}
            <button
              onClick={onClose}
              style={{
                background: 'none', border: 'none', cursor: 'pointer',
                width: 32, height: 32, borderRadius: '50%',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                color: '#6c757d', fontSize: '1.1rem',
                transition: 'background 0.15s',
              }}
              onMouseEnter={e => e.currentTarget.style.background = '#e9ecef'}
              onMouseLeave={e => e.currentTarget.style.background = 'none'}
              aria-label="Close"
            >
              ✕
            </button>
          </div>
        </div>

        {/* Body */}
        <div style={{ overflowY: 'auto', padding: '24px', flex: 1 }}>
  {loading ? (
    <div className="text-center py-5">
      <div className="spinner-border text-primary" role="status" />
      <div className="mt-2 text-muted small">Loading order…</div>
    </div>
  ) : !order ? (
    <div className="text-center py-5 text-muted">
      Failed to load order details.
    </div>
  ) : (
    <>
      {/* Order Details */}
      <div className="mb-4">
        <SectionLabel>Order Details</SectionLabel>

        <div className="row g-0">
          <InfoRow label="Order Number" value={order.orderNumber} />

          <InfoRow
            label="Order Date"
            value={
              order.orderDate
                ? new Date(order.orderDate).toLocaleDateString('en-IN')
                : null
            }
          />

          <InfoRow
            label="Delivery Date"
            value={
              order.deliveryDate
                ? new Date(order.deliveryDate).toLocaleDateString('en-IN')
                : null
            }
          />

          <InfoRow label="Design" value={order.design} />
          <InfoRow label="Design Type" value={order.designType} />

          <InfoRow label="Quantity" value={order.quantity} />
          <InfoRow label="Size" value={order.size} />

          <InfoRow label="Karat" value={order.karat} />
          <InfoRow label="Karat %" value={order.karatPercent} />

          <InfoRow label="Gold Colour" value={order.goldColour} />
          <InfoRow label="Gold Weight" value={order.goldWeight} />
        </div>
      </div>

      {/* Design Specification */}
      {order.designSpecification && (
        <div className="mb-4">
          <SectionLabel>Design Specification</SectionLabel>

          <div
            className="border rounded p-3 bg-light"
            style={{ whiteSpace: 'pre-wrap' }}
          >
            {order.designSpecification}
          </div>
        </div>
      )}

      {/* Stone & Diamond Details */}
      <div className="mb-4">
        <SectionLabel>Stone & Diamond Details</SectionLabel>

        <div className="row g-0">
          <InfoRow label="Stone Name" value={order.stoneName} />
          <InfoRow label="Diamond Quality" value={order.diamondQuality} />
          <InfoRow label="Diamond Weight" value={order.diamondWeight} />
          <InfoRow label="No. Of Diamonds" value={order.numberOfDiamonds} />

          <InfoRow
            label="Colour Stone Required"
            value={order.isColourRequired ? 'Yes' : 'No'}
          />

          <InfoRow
            label="Colour Stone Name"
            value={order.colourStoneName}
          />

          <InfoRow
            label="No. Of Colour Stones"
            value={order.numberOfColourStone}
          />

          <InfoRow
            label="Colour Stone Weight"
            value={order.colourStoneWeight}
          />

          <InfoRow
            label="Certificate Required"
            value={order.isCertificateRequired ? 'Yes' : 'No'}
          />

          <InfoRow
            label="Certificate Name"
            value={order.certificateName}
          />
        </div>
      </div>

      {/* Designer Details */}
      {(order.designerWeight ||
        order.designerDiamondWeight ||
        order.designerNumberOfDiamonds) && (
        <div className="mb-4">
          <SectionLabel>Designer Details</SectionLabel>

          <div className="row g-0">
            <InfoRow
              label="Designer Weight"
              value={order.designerWeight}
            />

            <InfoRow
              label="Designer Diamond Weight"
              value={order.designerDiamondWeight}
            />

            <InfoRow
              label="Designer Diamonds"
              value={order.designerNumberOfDiamonds}
            />
          </div>
        </div>
      )}

      {/* Final Production Details */}
      <div className="mb-4">
        <SectionLabel>Final Production Details</SectionLabel>

        <div className="row g-0">
          <InfoRow
            label="Final Gold Weight"
            value={order.finalGoldWeight}
          />

          <InfoRow
            label="Final Net Weight"
            value={order.finalNetWeight}
          />

          <InfoRow
            label="Final Diamond Weight"
            value={order.finalDiamondWeight}
          />

          <InfoRow
            label="Final Diamonds"
            value={order.finalNumberOfDiamonds}
          />

          <InfoRow
            label="Order Completed"
            value={order.isOrderCompleted ? 'Yes' : 'No'}
          />

          <InfoRow
            label="Completed Date"
            value={
              order.orderCompletedDate
                ? new Date(order.orderCompletedDate).toLocaleDateString(
                    'en-IN'
                  )
                : null
            }
          />
        </div>
      </div>

      {/* CAD Image */}
      {order.cadImage && (
        <div className="mb-4">
          <SectionLabel>CAD Design</SectionLabel>

          <img
            src={imgUrl(order.cadImage)}
            alt="CAD Design"
            className="rounded"
            style={{
              maxHeight: 220,
              cursor: 'zoom-in',
              objectFit: 'contain',
              border: '1px solid #e9ecef'
            }}
            onClick={() => setImgViewer(imgUrl(order.cadImage))}
          />
        </div>
      )}

      {/* Customer Images */}
      {['frontImage', 'topImage', 'sideImage', 'backImage'].some(
        f => order[f]
      ) && (
        <div className="mb-2">
          <SectionLabel>Customer Images</SectionLabel>

          <div className="d-flex gap-2 flex-wrap">
            {['frontImage', 'topImage', 'sideImage', 'backImage'].map(
              f =>
                order[f] && (
                  <div
                    key={f}
                    style={{ position: 'relative' }}
                  >
                    <img
                      src={imgUrl(order[f])}
                      alt={f}
                      onClick={() =>
                        setImgViewer(imgUrl(order[f]))
                      }
                      style={{
                        width: 90,
                        height: 90,
                        objectFit: 'cover',
                        borderRadius: 10,
                        cursor: 'zoom-in',
                        border: '2px solid #e9ecef'
                      }}
                    />

                    <span
                      style={{
                        position: 'absolute',
                        bottom: 4,
                        left: 4,
                        background: 'rgba(0,0,0,0.55)',
                        color: '#fff',
                        fontSize: '0.62rem',
                        borderRadius: 4,
                        padding: '1px 5px',
                        textTransform: 'capitalize'
                      }}
                    >
                      {f.replace('Image', '')}
                    </span>
                  </div>
                )
            )}
          </div>
        </div>
      )}
    </>
  )}
</div>

        {/* Footer */}
        <div style={{
          padding: '14px 24px',
          borderTop: '1px solid #e9ecef',
          background: '#f8f9fb',
          display: 'flex', justifyContent: 'flex-end',
        }}>
          <button className="btn btn-sm btn-secondary" onClick={onClose}>Close</button>
        </div>
      </div>

      {/* Full-size image viewer */}
      {imgViewer && (
        <div
          onClick={() => setImgViewer(null)}
          style={{
            position: 'fixed', inset: 0,
            background: 'rgba(0,0,0,0.88)',
            zIndex: 1060,
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            cursor: 'zoom-out',
          }}
        >
          <img
            src={imgViewer}
            alt="Full view"
            style={{ maxHeight: '90vh', maxWidth: '90vw', borderRadius: 8 }}
          />
        </div>
      )}
    </>
  );
};

const SectionLabel = ({ children }) => (
  <div style={{
    fontSize: '0.7rem',
    textTransform: 'uppercase',
    letterSpacing: '0.1em',
    color: '#6c757d',
    fontWeight: 600,
    marginBottom: 10,
    paddingBottom: 6,
    borderBottom: '1px solid #e9ecef',
  }}>
    {children}
  </div>
);

export default OrderViewModal;
